async function createPost(text: string, profile_ids: string[]) {
  try {
    const response = await client.post_v1_p({ text, profile_ids });
    console.log("Post creation response:", response);
    return response;
  } catch (error) {
    console.error("Failed to create post:", error);
    return null;
  }
}
```

